def act(obs, state):
    if "plan" not in state:
        plan = []
        cx, cy = WORLD_W // 2, WORLD_H // 2  # 60, 50

        # ── Power plants ─────────────────────────────────────────────────────
        # Primary coal plant left of center wire spine
        plant_x, plant_y = cx - 4, cy
        plan.append((Tool.COALPOWER, plant_x, plant_y))

        # ── Wire and road spines ──────────────────────────────────────────────
        wire_col = cx      # vertical wire spine at cx
        road_col = cx + 1  # vertical road spine at cx+1

        # Connect plant to wire spine horizontally
        for x in range(plant_x + 2, wire_col + 1):
            plan.append((Tool.WIRE, x, plant_y))

        # Vertical wire + road spine (center)
        for dy in range(-15, 16):
            y = cy + dy
            if 0 <= y < WORLD_H:
                plan.append((Tool.WIRE, wire_col, y))
                plan.append((Tool.ROAD, road_col, y))

        # Left road spine at cx-7
        road_left = cx - 7
        for dy in range(-15, 16):
            y = cy + dy
            if 0 <= y < WORLD_H:
                plan.append((Tool.WIRE, road_left - 1, y))
                plan.append((Tool.ROAD, road_left, y))

        # Right road spine at cx+8
        road_right = cx + 8
        for dy in range(-15, 16):
            y = cy + dy
            if 0 <= y < WORLD_H:
                plan.append((Tool.WIRE, road_right + 1, y))
                plan.append((Tool.ROAD, road_right, y))

        # Horizontal connecting roads every 3 rows for access
        for dy in range(-15, 16, 3):
            ry = cy + dy
            if 0 <= ry < WORLD_H:
                for x in range(road_left, road_right + 2):
                    if 0 <= x < WORLD_W:
                        plan.append((Tool.ROAD, x, ry))

        # ── Residential zones left of center spine ────────────────────────────
        # Centers at cx-3 (between left spine and wire spine)
        for dy in range(-13, 14, 3):
            zy = cy + dy
            if 1 <= zy <= WORLD_H - 2:
                plan.append((Tool.RESIDENTIAL, cx - 3, zy))

        # Centers at cx-10 (left of left spine)
        for dy in range(-13, 14, 3):
            zy = cy + dy
            if 1 <= zy <= WORLD_H - 2:
                plan.append((Tool.RESIDENTIAL, cx - 10, zy))

        # ── Residential/Commercial zones right of center spine ────────────────
        # Centers at cx+4 (between road spine and right spine)
        for dy in range(-13, 14, 3):
            zy = cy + dy
            if 1 <= zy <= WORLD_H - 2:
                if abs(dy) % 6 == 0:
                    plan.append((Tool.COMMERCIAL, cx + 4, zy))
                else:
                    plan.append((Tool.RESIDENTIAL, cx + 4, zy))

        # Centers at cx+11 (right of right spine)
        for dy in range(-13, 14, 3):
            zy = cy + dy
            if 1 <= zy <= WORLD_H - 2:
                if abs(dy) % 9 == 0:
                    plan.append((Tool.INDUSTRIAL, cx + 11, zy))
                else:
                    plan.append((Tool.RESIDENTIAL, cx + 11, zy))

        # ── Second coal plant for extra power ─────────────────────────────────
        plan.append((Tool.COALPOWER, cx + 15, cy - 6))
        # Connect second plant to right wire spine
        for x in range(road_right + 2, cx + 15):
            plan.append((Tool.WIRE, x, cy - 6))

        # ── Services ─────────────────────────────────────────────────────────
        plan.append((Tool.FIRESTATION, cx - 14, cy - 8))
        plan.append((Tool.POLICESTATION, cx - 14, cy + 5))
        plan.append((Tool.FIRESTATION, cx + 15, cy + 5))
        plan.append((Tool.POLICESTATION, cx + 15, cy - 12))

        state["plan"] = plan
        state["i"] = 0

    i = state["i"]
    plan = state["plan"]
    if i >= len(plan):
        return None
    state["i"] = i + 1
    tool, x, y = plan[i]
    x = max(0, min(WORLD_W - 1, x))
    y = max(0, min(WORLD_H - 1, y))
    return (tool, x, y)

