def act(obs, state):
    if "plan" not in state:
        plan = []

        # Strategy: Build a compact grid city centered at (60, 50)
        # with a power plant, proper wire connections, and mixed zones
        # arranged in a grid pattern with roads every 4 tiles

        cx, cy = 60, 50

        # Place coal power plant at top-left of city
        plan.append((Tool.COALPOWER, cx - 10, cy - 10))

        # Wire spine: horizontal from plant rightward at cy-10
        for x in range(cx - 10, cx + 15):
            plan.append((Tool.WIRE, x, cy - 10))

        # Wire spine: vertical from plant downward at cx-10
        for y in range(cy - 10, cy + 15):
            plan.append((Tool.WIRE, cx - 10, y))

        # Horizontal roads at cy-6, cy-2, cy+2, cy+6, cy+10
        road_rows = [cy - 6, cy - 2, cy + 2, cy + 6, cy + 10]
        for ry in road_rows:
            for x in range(cx - 12, cx + 14):
                plan.append((Tool.ROAD, x, ry))

        # Vertical roads at cx-8, cx-4, cx+0, cx+4, cx+8, cx+12
        road_cols = [cx - 8, cx - 4, cx + 0, cx + 4, cx + 8, cx + 12]
        for rx in road_cols:
            for y in range(cy - 8, cy + 13):
                plan.append((Tool.ROAD, rx, y))

        # Wire under horizontal roads to distribute power
        for ry in road_rows:
            for x in range(cx - 10, cx + 14):
                plan.append((Tool.WIRE, x, ry))

        # Wire along vertical roads to distribute power  
        for rx in road_cols:
            for y in range(cy - 10, cy + 13):
                plan.append((Tool.WIRE, rx, y))

        # Now re-place roads on top of wires (roads override wires)
        for ry in road_rows:
            for x in range(cx - 12, cx + 14):
                plan.append((Tool.ROAD, x, ry))
        for rx in road_cols:
            for y in range(cy - 8, cy + 13):
                plan.append((Tool.ROAD, rx, y))

        # Place zones in the grid cells
        # Grid cells are between road rows/cols
        # Zone centers should be at mid-points between roads
        # Roads at cols: cx-8, cx-4, cx+0, cx+4, cx+8, cx+12
        # Zone x centers (between road cols): cx-6, cx-2, cx+2, cx+6, cx+10
        # Roads at rows: cy-6, cy-2, cy+2, cy+6, cy+10
        # Zone y centers (between road rows): cy-4, cy+0, cy+4, cy+8

        zone_cols = [cx - 6, cx - 2, cx + 2, cx + 6, cx + 10]
        zone_rows = [cy - 4, cy + 0, cy + 4, cy + 8]

        # Mix of zone types: RES dominant, with COM and IND
        zone_types = [
            [Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL],
            [Tool.INDUSTRIAL,  Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL],
            [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,  Tool.RESIDENTIAL, Tool.RESIDENTIAL],
            [Tool.COMMERCIAL,  Tool.INDUSTRIAL,  Tool.RESIDENTIAL, Tool.INDUSTRIAL,  Tool.COMMERCIAL],
        ]

        for ri, zy in enumerate(zone_rows):
            for ci, zx in enumerate(zone_cols):
                ztype = zone_types[ri % len(zone_types)][ci % len(zone_cols)]
                plan.append((ztype, zx, zy))

        # Add fire and police stations
        plan.append((Tool.FIRESTATION, cx - 2, cy - 8))
        plan.append((Tool.POLICESTATION, cx + 6, cy - 8))

        # Second coal plant on the right side for more power
        plan.append((Tool.COALPOWER, cx + 14, cy - 10))
        # Wire connecting second plant leftward to main grid
        for x in range(cx + 10, cx + 15):
            plan.append((Tool.WIRE, x, cy - 10))

        # Re-place roads that may have been overwritten
        for ry in road_rows:
            for x in range(cx - 12, cx + 14):
                plan.append((Tool.ROAD, x, ry))
        for rx in road_cols:
            for y in range(cy - 8, cy + 13):
                plan.append((Tool.ROAD, rx, y))

        # Re-place zones that may have been overwritten
        for ri, zy in enumerate(zone_rows):
            for ci, zx in enumerate(zone_cols):
                ztype = zone_types[ri % len(zone_types)][ci % len(zone_cols)]
                plan.append((ztype, zx, zy))

        state["plan"] = plan
        state["i"] = 0

    i = state["i"]
    plan = state["plan"]

    if i >= len(plan):
        return None

    state["i"] = i + 1
    tool, x, y = plan[i]
    x = max(0, min(WORLD_W - 1, x))
    y = max(0, min(WORLD_H - 1, y))
    return (tool, x, y)

def build_plan():
    """
    Build a city with:
    - Three coal power plants strategically placed
    - A grid layout with roads and wires properly connected
    - Dense mix of residential, commercial, and industrial zones
    - Police and fire stations for city services
    - Zones arranged in a grid pattern for maximum density
    """
    plan = []

    # Center neighborhood - main cluster
    cx, cy = 60, 45

    # Power plant 1 - left side
    plan.append((Tool.COALPOWER, cx - 20, cy))
    # Wire connection from power plant to road grid
    for dx in range(-19, 0):
        plan.append((Tool.WIRE, cx + dx, cy))

    # Power plant 2 - right side  
    plan.append((Tool.COALPOWER, cx + 20, cy))
    # Wire connection from power plant to road grid
    for dx in range(1, 20):
        plan.append((Tool.WIRE, cx + dx, cy))

    # Main horizontal roads (3 parallel roads)
    for road_y in [cy - 8, cy - 4, cy, cy + 4, cy + 8]:
        for dx in range(-15, 16):
            plan.append((Tool.ROAD, cx + dx, road_y))

    # Main vertical roads (connecting horizontal roads)
    for road_x in [cx - 12, cx - 8, cx - 4, cx, cx + 4, cx + 8, cx + 12]:
        for dy in range(-10, 11):
            plan.append((Tool.ROAD, road_x, cy + dy))

    # Wire under horizontal roads for power distribution
    for road_y in [cy - 8, cy - 4, cy, cy + 4, cy + 8]:
        for dx in range(-15, 16):
